def px(lat, lon): return ((lon + 180) / 360 * W, (90 - lat) / 180 * H)
m = Image.new('L', (W, H), 0); d = ImageDraw.Draw(m)
for poly in [NA, GREEN, BAFFIN, ARCTIC, SA, AFRICA, MADA, EURASIA, CHUKOTKA] + ISLANDS:
    d.polygon([px(a, b) for a, b in poly], fill=255)
for poly in WATER: d.polygon([px(a, b) for a, b in poly], fill=0)
# Antarctica: wavy coast near 68-72 S with the peninsula toward South America
ant = []
for lon in np.arange(-180, 181, 4):
    lat = -70 + 2.5 * np.sin(np.radians(lon) * 3 + 1) + 1.5 * np.sin(np.radians(lon) * 7)
    if -75 < lon < -52: lat = max(lat, -63 - 0.25 * abs(lon + 60))
    ant.append((lat, lon))
d.polygon([px(a, b) for a, b in ant] + [px(-90, 180), px(-90, -180)], fill=255)
mask = np.asarray(m.filter(ImageFilter.GaussianBlur(3)), np.float32) / 255
# rough the coastlines with value noise
rng = np.random.default_rng(7)
def vnoise(scale):
    g = rng.random((int(H / scale) + 2, int(W / scale) + 2)).astype(np.float32)
    return np.asarray(Image.fromarray((g * 255).astype(np.uint8)).resize((W, H), Image.BICUBIC), np.float32) / 255
n1, n2, n3 = vnoise(48), vnoise(14), vnoise(5)
land = np.clip((mask - 0.5 + (n1 - 0.5) * 0.35 + (n2 - 0.5) * 0.25) * 6 + 0.5, 0, 1)
lat = (90 - (np.arange(H) + 0.5) / H * 180)[:, None] * np.ones((1, W)); lon = ((np.arange(W) + 0.5) / W * 360 - 180)[None, :] * np.ones((H, 1))
def box(la0, la1, lo0, lo1, soft=4):
    a = np.clip((lat - la0) / soft, 0, 1) * np.clip((la1 - lat) / soft, 0, 1) * np.clip((lon - lo0) / soft, 0, 1) * np.clip((lo1 - lon) / soft, 0, 1)
    return a
desert = np.clip(box(15, 33, -17, 35) + box(14, 31, 35, 60) + box(-32, -20, 118, 143, 5) + box(-28, -18, 14, 25) + box(26, 40, -118, -103) + box(37, 48, 56, 70) + box(38, 46, 90, 112) + box(24, 30, 62, 72), 0, 1)
desert = np.clip(desert * (0.75 + 0.5 * n1) - 0.1, 0, 1)
green = np.array([0.20, 0.33, 0.13]); jungle = np.array([0.10, 0.25, 0.08]); tan = np.array([0.66, 0.55, 0.36]); boreal = np.array([0.17, 0.24, 0.13]); tundra = np.array([0.36, 0.35, 0.28])
alat = np.abs(lat)[..., None]
jw = np.clip((alat - 6) / 18, 0, 1); lc = jungle * (1 - jw) + green * jw
lc = lc * (1 - np.clip((alat - 50) / 8, 0, 1)) + boreal * np.clip((alat - 50) / 8, 0, 1)
lc = lc * (1 - np.clip((alat - 63) / 6, 0, 1)) + tundra * np.clip((alat - 63) / 6, 0, 1)
lc = lc * (1 - desert[..., None]) + tan * desert[..., None]
lc = lc * (0.8 + 0.35 * n2[..., None] + 0.15 * n3[..., None])
ice = np.clip((alat[..., 0] - 72) / 3, 0, 1) + (lat < -60) * 1.0
gl = box(59, 84, -75, -10, 2) * (mask > 0.5)
ice = np.clip(np.maximum(ice, gl), 0, 1)[..., None]
lc = lc * (1 - ice) + np.array([0.86, 0.9, 0.95]) * ice
shallow = np.asarray(Image.fromarray((mask * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(10)), np.float32)[..., None] / 255
oc = np.array([0.02, 0.075, 0.2]) * (0.85 + 0.3 * n1[..., None]) + np.array([0.03, 0.12, 0.16]) * np.clip(shallow * 2.2, 0, 1)
oc = oc * (1 - np.clip((alat - 60) / 25, 0, 1) * 0.3)
rgb = lc * land[..., None] + oc * (1 - land[..., None])
img = np.concatenate([np.clip(rgb ** (1 / 2.2), 0, 1) * 255, land[..., None] * 255], 2).astype(np.uint8)
Image.fromarray(img, 'RGBA').save(sys.argv[1] if len(sys.argv) > 1 else 'earth.png')
Image.fromarray(img[..., :3]).resize((1024, 512)).save('earth_preview.jpg')
print('ok', img.shape)
